MAP = (
    "base",
    "surface",
    "overlay",
    "muted",
    "subtle",
    "text",
    None,
    None,
    "love",
    "gold",
    "rose",
    "pine",
    "foam",
    "iris",
    None,
    None,
)
DEFAULT_LIGHT = "rose-pine-dawn"
DEFAULT_DARK = "rose-pine-moon"


def palette(slug: str | None, variant: str) -> tuple[str, str, tuple[str, ...]]:
    """Falls back to the default of that variant when the slug is unknown."""
    got = SCHEMES.get(slug or "")
    if got and got[1] == variant:
        return got
    default = DEFAULT_LIGHT if variant == "light" else DEFAULT_DARK
    return SCHEMES[default]


def valid(slug: str | None, variant: str) -> str:
    """The slug if it exists with that variant, else that variant's default."""
    got = SCHEMES.get(slug or "")
    return slug if got and got[1] == variant else (DEFAULT_LIGHT if variant == "light" else DEFAULT_DARK)


def scheme_list(variant: str) -> list[tuple[str, str]]:
    return sorted((slug, v[0]) for slug, v in SCHEMES.items() if v[1] == variant)


def _vars(slug: str | None, variant: str) -> str:
    _, _, colors = palette(slug, variant)
    parts = [f"color-scheme:{variant}"]
    for i, name in enumerate(MAP):
        if name:
            parts.append(f"--{name}:{colors[i]}")
    parts.append(f"--hl-low:{colors[2]}")
    parts.append(f"--hl-med:{colors[3]}")
    parts.append(f"--hl-high:{colors[4]}")
    return ";".join(parts)


def css(light: str | None, dark: str | None) -> str:
    """Server-rendered palette: light by default, dark under prefers-color-scheme."""
    return (
        f":root{{{_vars(light, 'light')}}}\n"
        "@media (prefers-color-scheme:dark){"
        f":root{{{_vars(dark, 'dark')}}}}}"
    )
